-- Step 1: Create the archive table
CREATE TABLE annual_returns_archive (
    yearlyid bigint,
    portfolioref character varying,
    calendaryear bigint,
    fundperf real,
    categoryperf real
);

-- Step 2: Create the stored procedure to move old records to archive
CREATE OR REPLACE PROCEDURE archive_old_annual_returns(years_to_keep integer)
LANGUAGE plpgsql
AS $$
DECLARE
    cutoff_year bigint;
BEGIN
    -- Calculate the cutoff year: current year minus years to keep
    cutoff_year := EXTRACT(YEAR FROM CURRENT_DATE)::bigint - years_to_keep;

    -- Move old records into the archive table
    INSERT INTO annual_returns_archive (yearlyid, portfolioref, calendaryear, fundperf, categoryperf)
    SELECT yearlyid, portfolioref, calendaryear, fundperf, categoryperf
    FROM annual_returns
    WHERE calendaryear < cutoff_year;

    -- Delete archived records from the original table
    DELETE FROM annual_returns
    WHERE calendaryear < cutoff_year;
END;
$$;

-- Step 3: Call the procedure with a parameter (e.g., keep last 10 years)
CALL archive_old_annual_returns(10);
